#ifndef _WIN32
typedef double FLOAT;
#endif

#include "opl3.h"

/* Function pointer definitions matching QEMU/host timer signature */
typedef void (*OPL_TIMERHANDLER)(void *param, int timer_num, FLOAT delay);

/* Final production-ready Adapter context structure */
typedef struct fm_opl_adapter {
	opl3_chip chip;
	uint32_t sample_rate; /* Target audio mixing sample rate */
	uint16_t address_reg; /* Stores currently selected register latch */

	/* Cached register values for local software-timer delegation */
	uint8_t timer1_preset; /* Captured value from Register 0x02 */
	uint8_t timer2_preset; /* Captured value from Register 0x03 */
	uint8_t timer_control; /* Captured value from Register 0x04 */
	uint8_t status_mask;   /* Software state tracking for IRQ and Timer flags */

	/* Dynamically calculated timer steps based on input clock */
	uint64_t timer1_base_ns;
	uint64_t timer2_base_ns;

	/* Host callbacks and thread safety */
	OPL_TIMERHANDLER timer_handler;
	void *timer_param;  /* Context token passed to the handler */
	x_mutex_t lock;	    /* Mutex protecting the ring buffer and state */
} FM_OPL;

void *OPLCreate(uint32_t clock, uint32_t rate)
{
	FM_OPL *s = malloc(sizeof(FM_OPL));
	if (!s) return NULL;
	memset(s, 0, sizeof(FM_OPL));

	s->sample_rate = rate;

	/* Dynamic clock adaptation to support legacy OPL2 (3.58MHz) or OPL3 (14.32MHz) */
	if (clock == 0) clock = 14318180;
	s->timer1_base_ns = (8ULL * 1000000000ULL) / clock;
	s->timer2_base_ns = (32ULL * 1000000000ULL) / clock;

	/* Initialize Mutex to guarantee absolute thread safety */
	x_mutex_init(&s->lock, NULL);

	/* Initialize the Nuked-OPL3 chip core structure */
	OPL3_Reset(&s->chip, rate);
	return (void *)s;
}

void OPLSetTimerHandler(FM_OPL *s, OPL_TIMERHANDLER TimerHandler, void *param)
{
	s->timer_handler = TimerHandler;
	s->timer_param = param;
}

void OPLDestroy(FM_OPL *s)
{
	x_mutex_destroy(&s->lock);
	free(s);
}

void OPLTimerOver(FM_OPL *s, int timer_num)
{
	if (timer_num == 0) {
		s->status_mask |= 0x40; /* Set Timer 1 active flag */
		if (!(s->timer_control & 0x40)) { /* If not masked, raise global IRQ */
			s->status_mask |= 0x80;
		}
	} else if (timer_num == 1) {
		s->status_mask |= 0x20; /* Set Timer 2 active flag */
		if (!(s->timer_control & 0x20)) { /* If not masked, raise global IRQ */
			s->status_mask |= 0x80;
		}
	}
}

void OPLWrite(FM_OPL *s, uint32_t port, uint8_t value)
{
	uint32_t address_mapping = 0;

	switch (port & 3) {
	case 0: /* Port 0x388: Bank 0 Register Latch */
		s->address_reg = value;
		break;

	case 1: /* Port 0x389: Bank 0 Register Data Commit */
		address_mapping = (0x000 | s->address_reg) & 0x1FF;

		if (s->address_reg == 0x02) {
			s->timer1_preset = value;
		}
		else if (s->address_reg == 0x03) {
			s->timer2_preset = value;
		}
		else if (s->address_reg == 0x04) {
			s->timer_control = value;

			if (value & 0x80) {
				s->status_mask &= ~0xE0; /* Clear IRQ and Timer status bits */
				if (s->timer_handler) {
					s->timer_handler(s->timer_param, 0, 0); /* Disarm Timer 1 */
					s->timer_handler(s->timer_param, 1, 0); /* Disarm Timer 2 */
				}
				x_mutex_lock(&s->lock);
				OPL3_WriteRegBuffered(&s->chip, address_mapping, value);
				x_mutex_unlock(&s->lock);
				break;
			}

			if (s->timer_handler) {
				if ((value & 0x01) && !(value & 0x40)) {
					uint64_t delay = (uint64_t)(256 - s->timer1_preset) * s->timer1_base_ns;
					s->timer_handler(s->timer_param, 0, delay / 1000000000.0);
				} else {
					s->timer_handler(s->timer_param, 0, 0);
				}

				if ((value & 0x02) && !(value & 0x20)) {
					uint64_t delay = (uint64_t)(256 - s->timer2_preset) * s->timer2_base_ns;
					s->timer_handler(s->timer_param, 1, delay / 1000000000.0);
				} else {
					s->timer_handler(s->timer_param, 1, 0);
				}
			}
		}
		x_mutex_lock(&s->lock);
		OPL3_WriteRegBuffered(&s->chip, address_mapping, value);
		x_mutex_unlock(&s->lock);
		break;

	case 2: /* Port 0x38A: Bank 1 Register Latch */
		s->address_reg = value;
		break;

	case 3: /* Port 0x38B: Bank 1 Register Data Commit */
		address_mapping = (0x100 | s->address_reg) & 0x1FF;
		x_mutex_lock(&s->lock);
		OPL3_WriteRegBuffered(&s->chip, address_mapping, value);
		x_mutex_unlock(&s->lock);
		break;
	}
}

uint8_t OPLRead(FM_OPL *s, uint32_t port)
{
	uint8_t res = 0xFF;

	if (!(port & 1)) {
		/* Mirror legacy fmopl masking logic based on inverted timer control */
		uint8_t allowed_mask = (~s->timer_control) & 0x60;
		res = s->status_mask & (allowed_mask | 0x80);
	} else {
		switch (s->address_reg) {
		case 0x05:
		case 0x19:
		case 0x1a:
			res = 0;
			break;
		default:
			res = 0;
			break;
		}
	}
	return res;
}

void OPLGenerate(FM_OPL *s, int16_t *buffer, uint32_t samples)
{
	x_mutex_lock(&s->lock);
	/* Safely render interleaved stereo PCM data directly from Nuked-OPL3 core */
	OPL3_GenerateStream(&s->chip, buffer, samples);
	x_mutex_unlock(&s->lock);
}
